def sigmoid(z):
    return 1 / (1 + np.exp(-z))

def forward(X):
    global h
    h = np.tanh(X @ W1 + b1)
    return sigmoid(h @ W2 + b2)

def mse(out, y):
    return np.mean((out - y) ** 2)

def backward(X, y, out):
    d2 = 2 * (out - y) / len(X) * out * (1 - out)
    d1 = d2 @ W2.T * (1 - h ** 2)
    return {'W1': X.T @ d1, 'b1': d1.sum(0, keepdims=True), 'W2': h.T @ d2, 'b2': d2.sum(0, keepdims=True)}
